  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'يجب على منشئي المحتوى تقديم عناوين وأوصاف وفئات ولغات وصور مصغرة وتسميات توضيحية ومستوى رؤية وإعدادات جدولة دقيقة. مقاطع الفيديو المجدولة ليست عامة حتى وقتها المحدد ومعالجتها بنجاح.',
