  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'يتوفر التشغيل والتعليقات والإعجابات والمشاهدة لاحقًا والاشتراكات والإشعارات والرسائل وقوائم التشغيل وإعدادات اللغة من خلال قائمة التنقل الرئيسية والحساب.',
