  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub عبارة عن منصة فيديو لتحميل محتوى منشئي المحتوى ومشاهدته وجدولته وإدارته والإشراف عليه من حساب واحد.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub هو نظام أساسي للفيديو يعمل على هذا النشر، وهو مصمم للمبدعين والمشاهدين والمجتمعات ومشغلي النظام الأساسي.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'يوفر PlayHub قنوات منشئي المحتوى وتحميلات الفيديو والنشر المجدول والاشتراكات والتعليقات وقوائم التشغيل والمشاهدة لاحقًا وصفحات المحتوى المباشر وأدوات الإدارة من نظام أساسي واحد.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'يستخدم PlayHub ملفات تعريف الارتباط الأساسية وتخزين المتصفح لجلسات تسجيل الدخول، ومصادقة واجهة برمجة التطبيقات (API)، وسلوك CSRF/الأمان، واختيار اللغة، واختيار السمة، وحالة قائمة الحساب، والميزات الأخرى المطلوبة لكي يعمل التطبيق.',
