  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'حدد ملف فيديو واحدًا أو أكثر، وأدخل التفاصيل المطلوبة، واختر الفئة واللغة، وأضف صورة مصغرة، واختر الرؤية، ثم انشر. يتم تحميل الملفات الكبيرة على أجزاء قبل أن يبدأ الخادم في المعالجة.',
  'Send a message and it will be saved for admins.' => 'أرسل رسالة وسيتم حفظها للمسؤولين.',
  'Send billing details to admin support for review.' => 'أرسل تفاصيل الفواتير إلى دعم المشرف للمراجعة.',
  'Send message' => 'أرسل رسالة',
  'Send order details through the refund popup.' => 'أرسل تفاصيل الطلب من خلال نافذة استرداد الأموال المنبثقة.',
  'Send us a message' => 'أرسل لنا رسالة',
  'Sending...' => 'جارٍ الإرسال...',
  'Server configured' => 'تم تكوين الخادم',
  'server records' => 'سجلات الخادم',
  'Service operation' => 'عملية الخدمة',
  'session, token' => 'جلسة، رمز',
  'Settings and login' => 'الإعدادات وتسجيل الدخول',
  'Short summary' => 'ملخص قصير',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'قم بتسجيل الدخول واستخدم الإعدادات للحساب والملف الشخصي وكلمة المرور والإشعارات والخصوصية وتفضيلات المنشئ. يجب أن تتضمن مشكلات التحميل والمحتوى الخاصة بمنشئ المحتوى عنوان الفيديو والقناة والمتصفح وأي خطأ في المعالجة يظهر على صفحة التحميل.',
  'Sign in for account support' => 'قم بتسجيل الدخول للحصول على دعم الحساب',
  'Signed in' => 'تم تسجيل الدخول',
  'Start uploading' => 'ابدأ التحميل',
  'Still can’t find an answer?' => 'هل ما زلت لا تستطيع العثور على إجابة؟',
  'Stored for admins' => 'مخزنة للمسؤولين',
  'Stores language, theme, and interface preferences.' => 'يخزن اللغة والموضوع وتفضيلات الواجهة.',
  'Studio, playlists, analytics, channels.' => 'الاستوديو وقوائم التشغيل والتحليلات والقنوات.',
  'Submit a billing or refund message to admin support.' => 'أرسل رسالة الفوترة أو استرداد الأموال إلى دعم المشرف.',
  'Submit refund request' => 'إرسال طلب استرداد',
  'Submit request' => 'إرسال الطلب',
  'Subscription cancellation' => 'إلغاء الاشتراك',
  'Support dashboard' => 'لوحة الدعم',
  'System status' => 'حالة النظام',
  'Table' => 'الجدول',
  'Taxonomies' => 'التصنيفات',
  'Technical issue' => 'مسألة فنية',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'ملاحظات فنية لعمليات التكامل مع واجهة برمجة تطبيقات PlayHub الحالية وسير عمل التحميل.',
  'Tell us more about your question or request...' => 'أخبرنا المزيد عن سؤالك أو طلبك...',
  'Terms of Use' => 'شروط الاستخدام',
  'The configured' => 'تم تكوينه',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ترتبط صفحة المطور بالواجهة الخلفية المباشرة لـ Laravel: يتم تحميل مسار المخزون، وأعداد قاعدة البيانات، وحدود التحميل، وبيانات تعريف النظام الأساسي من /api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'تقوم الواجهة الأمامية بتخزين التفضيلات مثل اللغة المحددة والموضوع وقائمة انتظار التشغيل ومراقبة التقدم وحالة الواجهة بحيث تظل التجربة متسقة عبر التنقل في الصفحة وعمليات إعادة التحميل.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'تقوم مهمة المعالجة بتشفير عمليات الترحيل، وإنشاء الصور المصغرة عند الحاجة، وتخزين التسميات التوضيحية، ووضع علامات على مقاطع الفيديو الجاهزة عند اكتمال المعالجة. تظل مقاطع الفيديو المجدولة المستقبلية خاصة حتى يقوم المجدول بإصدارها.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'نظام التحميل مدعوم بقاعدة بيانات، ويدعم الفئات واللغات من واجهة برمجة التطبيقات (API)، ويعالج مقاطع الفيديو التي تم تحميلها، ويخزن الصور المصغرة والتسميات التوضيحية، ويحافظ على خصوصية المحتوى المجدول حتى وقت إصداره.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'تشرح هذه الصفحة كيفية استخدام PlayHub لملفات تعريف الارتباط وتخزين المتصفح للجلسات والأمان والتفضيلات والتشغيل والميزات المصادق عليها.',
  'Ticket source' => 'مصدر التذكرة',
  'Top content categories' => 'أهم فئات المحتوى',
  'Topic' => 'الموضوع',
  'Transaction / invoice' => 'المعاملة / الفاتورة',
  'Transaction / invoice ID' => 'معرف المعاملة/الفاتورة',
  'Unable to send message.' => 'غير قادر على إرسال الرسالة.',
  'Unable to submit refund request.' => 'غير قادر على تقديم طلب استرداد.',
  'Understanding admin support tickets' => 'فهم تذاكر دعم المشرف',
  'Upload and processing help' => 'مساعدة في التحميل والمعالجة',
  'Upload chunks' => 'تحميل قطع',
  'Upload issues' => 'تحميل القضايا',
  'Upload languages' => 'تحميل اللغات',
  'Upload limit' => 'حد التحميل',
  'Upload options' => 'خيارات التحميل',
  'Upload or processing' => 'التحميل أو المعالجة',
  'Upload page' => 'تحميل الصفحة',
  'Upload pipeline' => 'تحميل خط الأنابيب',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'يمكنك التحميل والمشاهدة والاشتراك والإشراف والإنشاء باستخدام بيانات PlayHub المباشرة.',
  'Uploaded videos' => 'مقاطع الفيديو التي تم تحميلها',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'يتم ترميز مقاطع الفيديو التي تم تحميلها في إصدارات قابلة للتشغيل. يعتمد وقت المعالجة على حجم الملف ومدته وتحميل الخادم وحالة قائمة الانتظار. تعرض صفحة التحميل واستوديو منشئي المحتوى حالة المعالجة الحقيقية من سجل الفيديو.',
  'Uploads, scheduling, and processing are available.' => 'تتوفر عمليات التحميل والجدولة والمعالجة.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'استخدم /api/videos ونقاط نهاية القناة والمسارات المعتمدة لسير عمل منشئي المحتوى.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'استخدم إجراءات التقرير المضمنة لمقاطع الفيديو والتعليقات حتى يتلقى المسؤولون مرجع المحتوى الدقيق. تستخدم صفحات لوحة تحكم المشرف بيانات قاعدة البيانات المباشرة للمستخدمين والمحتوى والتقارير وتحقيق الدخل والتحليلات والدعم والأدوار وإعدادات النظام.',
  'Use Contact Us' => 'استخدم اتصل بنا',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'استخدم JSON لطلبات واجهة برمجة التطبيقات العادية وFormData لتحميل الملفات. لا تتجاوز التحقق من الصحة: ​​الفئات واللغات هي معرفات قاعدة البيانات، وتقتصر الرؤية على العامة أو غير المدرجة أو الخاصة، وتقبل التسميات التوضيحية ملفات SRT أو VTT أو TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'استخدم الإعدادات لتحديث ملف التعريف والأمان وكلمة المرور والتسليم الثنائي والأجهزة والتفضيلات وخيارات الإشعارات. إذا لم تتمكن من الوصول إلى حسابك، استخدم تدفق تسجيل الدخول وقم بتقديم البريد الإلكتروني للحساب إلى مسؤول الموقع.',
  'Use the contact form' => 'استخدم نموذج الاتصال',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'استخدم إجراءات التقرير على مقاطع الفيديو والتعليقات ومنشورات المجتمع حتى يتلقى المسؤولون مرجع المحتوى الدقيق.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'استخدم إجراءات الإبلاغ على مقاطع الفيديو والتعليقات والمشاركات المجتمعية عندما ينتهك المحتوى قواعد النظام الأساسي. ترتبط هذه التقارير بسجل المحتوى الحقيقي وهي أفضل من الرسائل العامة لأنه يمكن للمسؤولين مراجعة العنصر المحدد.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'استخدم قناة PlayHub المناسبة للحصول على مساعدة الحساب وتقارير المحتوى والمشكلات الفنية وطلبات المسؤول.',
  'Video categories' => 'فئات الفيديو',
  'Video for everyone. Built for creators and viewers.' => 'فيديو للجميع. بنيت من بيانات منصة حقيقية.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'مشكلات تحميل الفيديو والجدولة والصور المصغرة والمعالجة.',
  'Videos, thumbnails, captions, processing.' => 'مقاطع الفيديو والصور المصغرة والتعليقات التوضيحية والمعالجة.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'يمكن للمشاهدين تصفح الفئات والبحث في مقاطع الفيديو ومشاهدة المحتوى والاشتراك في القنوات وحفظ مقاطع الفيديو لمشاهدتها لاحقًا والتعليق وتلقي الإشعارات وإدارة تفضيلات اللغة وإمكانية الوصول.',
  'Viewing and community help' => 'عرض ومساعدة المجتمع',
  'Waiting for backend endpoint inventory.' => 'في انتظار مخزون نقطة النهاية الخلفية.',
  'We’re here to help.' => 'نحن هنا للمساعدة.',
  'What is PlayHub?' => 'ما هو بلاي هاب؟',
  'What PlayHub does' => 'ما يفعله PlayHub',
  'Where do contact messages go?' => 'أين تذهب رسائل الاتصال؟',
  'Why is my video still processing?' => 'لماذا لا يزال الفيديو قيد المعالجة؟',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'نعم. استخدم حقل تاريخ ووقت الجدول الأصلي في صفحة التحميل. تقوم الواجهة الخلفية بتخزين جدولة_at، ومعالجة الفيديو، والحفاظ على خصوصيته عندما يكون التاريخ في المستقبل، وإصداره عندما يعمل برنامج جدولة Laravel بعد الوقت المحدد.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'نعم. استخدم حقل الجدول الأصلي في التحميل. تقوم الواجهة الخلفية بتخزين جدول زمني وإصدار الفيديو بعد المعالجة عند الوصول إلى وقت الجدول الزمني.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'أنت تتصفح كضيف. قم بتسجيل الدخول للوصول إلى الأدوات الخاصة بالحساب.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'أنت مسؤول عن بيانات اعتماد حسابك ونشاط ملفك الشخصي والمحتوى الذي تم تحميله والتعليقات والرسائل وأي إجراءات منشئ أو مسؤول يتم تنفيذها من حسابك. استخدم كلمات مرور قوية وحافظ على تحديث طرق التسليم الثنائية.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'يمكنك مسح ملفات تعريف الارتباط للمتصفح والتخزين المحلي في إعدادات المتصفح الخاص بك. قد يؤدي مسح مساحة التخزين الأساسية إلى تسجيل خروجك وإعادة تعيين تفضيلات اللغة/الموضوع وإزالة حالة التشغيل المحلية ومطالبتك بتسجيل الدخول مرة أخرى.',
  'You receive a response by email.' => 'تتلقى ردا عن طريق البريد الإلكتروني.',
  'You’re in control' => 'أنت المسيطر',
  'Your choices' => 'اختياراتك',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'يتم حفظ رسالتك مباشرة في الواجهة الخلفية لموقع الويب وتظهر في لوحة تحكم المسؤول ضمن الدعم.',
